 "シナリオの JSON をコピーしました": "Copied the scenario JSON",
 "コピーできません": "Cannot copy",
 "{0}対{1}": "{0} vs {1}",
 "{0}の艦隊": "{0} Fleet",
 "費用は設計から計算した建造費（船体・装甲・動力・推進・武装などの部品ごとの単価の合計）に、乗員の育成費 1名 {0} と艦載機・搭載艦を加えたものです（仮の算式・調整可能）。": "Cost is the build cost calculated from the design (the sum of each part's unit price: hull, armor, power, propulsion, weapons and so on), plus crew training at {0} a head and the craft and embarked ships (a provisional, tunable formula).",
 "シナリオの形式ではありません": "Not a scenario file",
 "新しい版のシナリオです（読み込めません）": "A scenario from a newer version (cannot be loaded)",
