  "{0}（内蔵冷却）": "{0} (Built-in Cooling)",
  "自動割当の散逸（{0}）": "Auto-assigned Dissipation ({0})",
  "反応炉・武装・推進・シールド・生活設備・超兵器は一つの給電網と熱輸送網につながります。廃熱は消費電力のうち砲弾・排気・有効出力として出ていかない分です。各設備の内蔵冷却で足りない熱は熱輸送路で近くの散逸設備へ運ばれ、運びきれない分は設備に蓄熱します。蓄熱が増えると出力制限、満杯で緊急停止します。停止が間に合わないと武装は武装用電力区画が焼損し、超兵器は直結したジェネレーターが爆発します。超兵器は内蔵冷却を持たないので、散逸装置がない場合はジェネレーターに散逸能力を自動割当します。低放射持続は、散逸を止めて全廃熱を蓄熱した場合に続けられる時間です。数値はすべて仮の調整値です。": "Reactors, weapons, propulsion, shields, life support and superweapons share one power network and one heat-transport network. Waste heat is the part of the power drawn that does not leave as bolts, exhaust or useful output. Heat a device's built-in cooling cannot handle is carried along heat paths to nearby dissipators; what the paths cannot carry is stored in the device. As stored heat rises, output is limited; when full, the device shuts down. If the shutdown comes too late, a weapon burns out its weapon power compartment and a superweapon blows up the generator wired to it. Superweapons have no built-in cooling, so without dissipators their generator is auto-assigned dissipation. Low-emission endurance is how long the load can be held with dissipation stopped and all waste heat stored. All figures are provisional tuning values.",
  "船体内部に置く高エネルギー散逸装置（スター・ウォーズの架空技術）。内部容積・質量を使い、近くの熱源から熱輸送路で廃熱を受けて処理します。武装・反応炉・推進・シールド・超兵器のどの熱も扱えます。": "A high-energy dissipator mounted inside the hull (fictional Star Wars technology). It takes internal volume and mass and receives waste heat from nearby sources along heat paths. It handles heat from weapons, reactors, propulsion, shields and superweapons.",
  "外殻・主翼の外面に張り出させる高エネルギー散逸装置（架空技術）。容積あたりの能力が高い一方、外に出ている分だけ被弾しやすい弱点です。船外に出ている割合に応じて能力が決まります。": "A high-energy dissipator that projects from the hull or wing surface (fictional technology). It has more capacity per volume, but what is exposed is a weak point that is easier to hit. Its capacity depends on how much of it is outside the hull.",
  "電子機器・生活設備などの低温の廃熱だけを処理する放熱装置。武装や炉の高エネルギーの廃熱は扱えません。船外に出ている割合が大きいほど能力が上がります。": "A radiator for low-grade waste heat only, such as electronics and life support. It cannot handle the high-energy waste heat of weapons or reactors. The more of it is outside the hull, the greater its capacity.",
  "給電経路のない設備が {0} 系統あります（断線）。": "{0} systems have no power path (broken).",
  "接続できない熱輸送路が {0} 本あります（相手がない、または通常放熱装置に高エネルギーの廃熱）。": "{0} heat paths cannot connect (missing endpoint, or high-energy heat routed to an ordinary radiator).",
  "戦闘負荷で {0} 系統の廃熱が処理しきれず蓄熱します（最短 {1} で出力制限）。散逸装置か熱輸送路を足してください。": "At combat load, {0} systems cannot shed their waste heat and store it (output limited in {1} at the earliest). Add dissipators or heat paths.",
  "最大出力では {0} 系統が蓄熱します（最短 {1} で出力制限）。散逸装置を足すと全力運転を続けられます。": "At maximum output, {0} systems store heat (output limited in {1} at the earliest). More dissipators let the ship sustain full power.",
  "超兵器 {0} 基の直結系統に散逸装置がつながっていないため、ジェネレーターに散逸能力を自動割当しています。": "No dissipator is connected to the direct systems of {0} superweapons, so their generators are auto-assigned dissipation.",
  "{0}：過熱 {1}%・出力制限": "{0}: Overheating {1}%, output limited",
  "{0}：過熱 {1}%・緊急停止を開始": "{0}: Overheating {1}%, emergency shutdown started",
  "{0}：緊急停止（冷却まで停止）": "{0}: Emergency shutdown (stopped until cooled)",
  "{0}：安全停止に失敗（蓄熱 {1}%）": "{0}: Safe shutdown failed (stored heat {1}%)",
  "{0}：遅れて停止": "{0}: Shut down late",
  "{0}：冷却完了・再起動": "{0}: Cooled, restarted",
  "{0} 過熱で損傷・停止": "{0} damaged by overheating and stopped",
  "{0}：重大な過熱が続き武装用電力区画が焼損（{1} 基が射撃不能）": "{0}: Sustained critical overheating burned out the weapon power compartment ({1} weapons cannot fire)",
  "{0} が過負荷で爆発（{1} の直結系統の過熱）": "{0} exploded from overload (overheating of the {1} direct system)",
  "{0}：過熱で重大損傷": "{0}: Critical overheating damage",
