  "艦の3D表示。ドラッグで回転、2本指で拡大と移動、タップで操作": "3D ship view. Drag to rotate, use two fingers to zoom and pan, and tap to interact.",
  "艦隊編成図。艦の記号をタップして選択。ドラッグで平行移動、2本指やホイールで拡大縮小。矢印キーで移動、プラスとマイナスで拡大縮小、0で全体表示": "Fleet map. Tap a ship to select it. Drag to pan; pinch or scroll to zoom. Arrow keys pan, +/− zoom, and 0 fits all ships.",
  "状況図を表示できません。艦隊一覧から艦を選択し、「座標で移動を指定」で命令を設定できます。": "Tactical display unavailable. Select ships in the fleet list and issue coordinate movement orders.",
