  "新しいカッター": "New Cutter",
  "元に戻す・やり直す操作にも対応します。": "Undo and Redo are supported.",
  "立体を重ねて切り取る": "Cut with an Overlapping Solid",
  "面をタップ": "Tap a Surface",
  "表示中の立体の内側が切り取られる範囲です。": "The inside of the displayed solid is the region to remove.",
  "重なりを切り取る": "Cut the Overlap",
  "切り取った箇所をここから調整・取り消しできます。": "Adjust or remove previous cuts here.",
