  "この艦級を複製": "Duplicate This Ship Class",
  "未乗艦": "Not Embarked",
  "旗艦に": "Make Flagship",
  "陣営と戦域": "Faction and Theater",
  "任務マップで選ぶ": "Choose on Mission Map",
  "編成枠": "Deployment Budget",
  "敵の戦力": "Enemy Strength",
  "推定戦力比": "Estimated Strength Ratio",
  "出撃させる任務群": "Task Forces to Deploy",
  "すべて選ぶ": "Select All",
  "編成を変える": "Edit Organization",
  "。自動交戦の艦はシールドの残る敵にイオン砲を集中し、爆撃機の飛行隊はシールドが落ちた艦だけを攻撃します。": ". Ships using automatic engagement focus ion cannons on shielded enemies; bomber wings attack only ships whose shields are down.",
  "総乗員数（乗組員・操縦士・陸戦隊）": "Total Personnel (Crew, Pilots, and Troops)",
  "資材（補給品・予備品）": "Materials (Supplies and Spare Parts)",
  "輸送機（艦隊戦では艦内に待機）": "Transport (Stays Aboard During Fleet Battles)",
  "搭載・発艦可": "Embarked / Can Launch",
  "お任せ（史実の搭載）": "Automatic (Canonical Complement)",
  "すべて降ろす": "Disembark All",
  "格納庫（機体・搭載艦・車両で共用）": "Shared Hangar: Craft, Ships, and Vehicles",
  "機数": "Craft Count",
  "お任せ（史実の陸戦隊）": "Automatic (Canonical Ground Forces)",
  "連隊は4個大隊、大隊は4個中隊（144名）。乗艦した陸戦隊は拿捕のときに移乗攻撃の兵力になります。車両は輸送機の積載区画か格納庫（航空機と共用）に寸法で入ります。": "A regiment contains four battalions, each with four 144-person companies. Embarked troops provide boarding strength for captures. Vehicles must fit inside transport cargo bays or the shared hangar.",
  "兵員枠（空き容積から定員を除く）": "Troop Berths (Free Volume after Required Crew)",
  "車両と降下": "Vehicles and Deployment",
  "発射管・爆弾倉・パイロンごとに指定": "Set per Tube, Bomb Bay, or Pylon",
  "戦力": "Strength",
  "合同任務群を選ぶと、配下の任務群をそろえてジャンプさせられます。艦隊は航路（主要幹線・支線）に沿ってだけ移動します。": "Select a combined task force to synchronize its task forces' jumps. Fleets travel only along hyperspace routes, including main lanes and branches.",
  "円筒形の超空間航行装置。外殻内に収まる実容積と艦の質量からクラスを計算する。クラスは小さいほど高速。": "Cylindrical hyperspace drive. Class is calculated from usable internal volume and ship mass. Lower classes are faster.",
  "鏃形": "Arrowhead",
  "箱形": "Box",
  "円盤形": "Disc",
  "槍形": "Spear",
  "矩形": "Rectangle",
  "スターファイター": "Starfighter",
  "小型艇（シャトル・揚陸艇）": "Small Craft (Shuttle / Landing Craft)",
  "ラムダ級 20 m・LAAT/i 17.7 m・センチネル級 38 m": "Lambda 20 m · LAAT/i 17.7 m · Sentinel 38 m",
  "CR90 150 m・レイダー級 150 m": "CR90 150 m · Raider 150 m",
  "ネビュロンB 300 m": "Nebulon-B 300 m",
  "軽巡洋艦の大きさ": "Light Cruiser Size",
  "ドレッドノート級重巡洋艦 600 m": "Dreadnaught Heavy Cruiser 600 m",
  "アリージャンス級 2,200 m": "Allegiance 2,200 m",
  "前方": "Forward",
  "後方": "Aft",
  "上方": "Above",
  "下方": "Below",
  "非武装": "Unarmed",
  "ジェネレーターがありません。出力ゼロでは何も動きません。": "No generator. Nothing operates without power.",
  "エンジンがありません。": "No engines installed.",
  "艦橋がありません。命中率が大きく落ちます。": "No bridge. Accuracy is greatly reduced.",
  "シールド発生器がありません。": "No shield generators installed.",
  "ハイパードライブがありません（星系内専用艦）。": "No hyperdrive: restricted to travel within a system.",
  "全陣営": "All Factions",
  "防御・船体維持": "Defense & Hull Support",
  "航空・輸送": "Aviation & Transport",
  "炉との間を機関として自動占有。接続炉・向き・口径を調整できます。": "Automatically reserves machinery space between nozzle and reactor. Adjust the reactor connection, direction, and diameter.",
  "主反応炉と同じ容積あたりの出力を持つ補助炉。独立したノズルの接続先にもできます。": "Auxiliary reactor with the same power density as the main reactor. It can also power independently connected nozzles.",
  "反応物を貯蔵。搭載量と出力から巡航時の持続時間を算出します。": "Stores reactants. Cruise endurance is calculated from stored fuel and reactor output.",
  "ポンプ・弁・供給設備。搭載量に応じて燃料供給能力を確保します。": "Pumps, valves, and feed systems. Fuel delivery capacity depends on installed equipment volume.",
  "電力の蓄積設備。武装への配電の起点で、近くの砲ほど配電路が短く済みます（出せる電力は蓄電量を30秒で出し切る分まで、残りは炉から直接）。戦闘ではシールドへの給電を肩代わりし、炉の出力を推進や兵装に回している間もシールドを再生させます。満充電のシールドの余剰給電で充電され、イオン砲の被弾で奪われます。": "Energy storage and a distribution point for nearby weapons, reducing conduit length. Maximum output empties the stored energy in 30 seconds; additional power comes directly from reactors. In combat it can power shield regeneration while reactor output supports engines or guns. Surplus power to fully charged shields recharges the cells; ion hits drain them.",
  "慣性制御装置の対応質量が不足しています。": "Inertial compensation capacity is insufficient for the ship's mass.",
  "構造維持装置の対応質量が不足しています。": "Structural integrity field capacity is insufficient for the ship's mass.",
  "ヴェネター 航空指揮艦橋本体": "Venator Flight Command Bridge Body",
  "ヴェネター 航行艦橋本体": "Venator Navigation Bridge Body",
  "インペリアルI級 艦橋本体（ハンマーヘッド）": "Imperial I-class Bridge Body (Hammerhead)",
  "VLS弾庫": "VLS Magazine",
  "ミサイルのセルと弾庫。発射機の下に船内容積を確保します。周辺区画と干渉すると、必要容積を保って空き空間に形を組み替えます。": "Missile cells and magazine beneath a launcher. If nearby compartments overlap, the required volume is reshaped into available space.",
  "TIE/sa ボマー": "TIE/sa Bomber",
  "V-19 トレント": "V-19 Torrent",
