  "主砲充電装置 {0} 基の必要容積を確保できません。自動統合の範囲内に空間を空けるか、構造を追加してください。": "Insufficient volume for {0} main-gun charging units. Clear space within the integration area or add structure.",
  "{0}{1} の機体が入る格納区画がありません（全長・全幅・全高に {2} m の余裕が要ります）。格納区画を大きくするか、機種を変えてください。": "No hangar fits {0}{1} (requires {2} m clearance in length, width, and height). Enlarge the compartment or change craft type.",
