  "炉を80%に抑えて推進を優先。被弾時の誘爆率が最も低い。": "Limit reactor output to 80% and prioritize propulsion. Lowest risk of detonation when hit.",
  "シールド維持→推進→兵装充電の順。停止すると兵装に多く回る。": "Prioritize shield maintenance, then propulsion, then weapon charging. More power reaches weapons when stopped.",
