  "この本体を指揮所として使う": "Use This Body as a Command Center",
  "モデル由来の艦橋本体は、それ自体が{2}の指揮所です。ポッドや窓を足す必要はありません。{3}": "This model-derived bridge body already serves as a {2} command center. No additional pods or windows are needed.{3}",
  "稼働 {0}": "Operational {0}",
  "インペリアル級艦橋の円筒形ポッドです。構造物の側面や前後の壁に取り付けると、その役割の指揮所になります。甲板と船体には置けません。ポッドの背後には指揮区画が確保されます。インペリアル級・ヴェネター級の艦橋本体は、ポッドを足さなくても艦橋として機能します。": "Cylindrical Imperial-class bridge pods. Mounted on a structure's side, front or rear wall, each serves as a command center for its assigned role. They cannot mount on decks or hull surfaces. Command space is reserved behind each pod. Imperial-class and Venator-class bridge bodies function as bridges without added pods.",
  "無窓式指揮室を配置する": "Place an Enclosed Command Center",
  "ポッドを設置": "Mount Pod",
