  "この艦が入る格納区画がありません。全長・全幅・全高とも {0} m の余裕が要ります。": "No hangar compartment can hold this ship. It needs {0} m clearance in length, width and height.",
  "格納庫の空きか配置が足りず {0} 隻が未搭載。": "{0} ships could not embark because of insufficient space or unsuitable hangar layout.",
  "{0} 隻は、通れる大きさのハッチ（開口 {1} 以上）につながる区画に入らないため発進できません。": "{0} ships cannot launch because they are not in a compartment linked to a large enough hatch (opening at least {1}).",
  "外形 {0}{1} · 1機 サイズ {2} · 搭載 {3} / {4} 機{5}": "Dimensions {0}{1} · Size per Craft {2} · Embarked {3} / {4} Craft{5}",
