  "輸送機：1機で兵員 {0} 名{1}を降ろします。": "Transport: each craft lands {0} troops{1}.",
  "、車両 {0} サイズ（{1} まで）": " and {0} vehicle size units (up to {1})",
  "この機体が入る格納区画がありません。全長・全幅・全高とも {0} m の余裕をもって入る内寸の区画が要ります（機首はどちらの水平方向にも向けられます）。": "No hangar compartment can hold this craft. Internal dimensions need {0} m clearance in length, width and height. The nose can face either horizontal axis.",
  "格納庫の空きか配置が足りず {0} 機が未搭載。上の航空隊から順に収容します。": "{0} craft could not embark because of insufficient space or unsuitable hangar layout. Air wings are stowed in the order shown above.",
