  "設計機：{0}（{1}）。航行では空母からこの性能で出撃します。": "Custom Craft: {0} ({1}). Carrier operations use these performance figures.",
  "1機のサイズ": "Size per Craft",
  "航空隊 {4} の機体サイズ": "Air Wing {4} Craft Size",
  "ハッチ化しない": "No Hatch",
  "開放型": "Open Bay",
  "この区画はほぼ全体が船体の外（切り取った空間など）にあり、使える容積がありません。区画の一部が切り取った面の奥（船体の内側）に入るよう、位置か寸法を調整してください。": "This compartment lies almost entirely outside the hull, such as in a cutout, and has no usable volume. Adjust its position or dimensions so part extends behind the cut surface into the hull.",
  "表面に接触した面の開口": "Openings on Contact Surfaces",
  "航空区画を船体・外装の表面まで広げ、接触した面の方式を選びます。切り取った凹みの天井や壁に接した面も開口できます。開口は区画の位置と大きさに追従します。": "Extend the aviation compartment to the hull or outer surface and choose an opening type for each contacting face. Faces touching the ceiling or walls of a recess can also open. Openings follow the compartment's position and dimensions.",
  "{5} {6}の開口方式": "{5} {6} Opening Type",
  "装甲スライド扉を併設": "Add Armored Sliding Doors",
  "接触面積": "Contact Area",
  "未接触 ·": "No Contact ·",
  "の設定を保持。表面に再び接触すると開口が戻ります。": " setting retained. The opening returns when the compartment touches the surface again.",
  "船体・外装の表面に接触していません。区画の位置・寸法を調整すると選択できます。": "Not touching a hull or outer surface. Adjust position or dimensions to enable selection.",
  "航空区画の用途と容量": "Aviation Compartment Function and Capacity",
  "用途": "Function",
  "この区画の容量": "This Compartment's Capacity",
  "外殻内で使える実容積から計算します。格納・兼用区画を大きくすると容量が増え、飛行・移送甲板とドッキング区画は格納容量に含みません。機体・車両が入るかは区画の内寸（全長・全幅・高さ）で、発艦できるかは出入口の開口で決まります。": "Calculated from usable volume inside the outer shell. Enlarging stowage or multipurpose compartments increases capacity; flight/transfer decks and docking compartments add no stowage capacity. Internal length, width and height determine whether craft or vehicles fit, while the entrance opening determines whether they can launch.",
  "航空隊の機種・機数を編集": "Edit Air Wing Types / Quantities",
  "スライド扉の開き": "Sliding Door Opening",
  "{5} {6}の扉の開き": "{5} {6} Door Opening",
  "表面に接触していないため、開口は無効です。": "Opening disabled: the compartment is not touching an exterior surface.",
  "{3}{4} · {5} m · サイズ {6}{7}": "{3}{4} · {5} m · Size {6}{7}",
  "（入らない）": "(Does Not Fit)",
  "艦艇を搭載": "Embark Ships",
  "小型の艦も、艦載機と同じ「サイズ」に換算して格納庫に積めます（外形の全長×全幅×全高に {0} m ずつ足した容積 × {1} ÷ 艦載機1機分の格納容積）。格納・兼用区画のどれか一つに丸ごと入る艦だけを選べます。保存した設計も選べます。": "Small ships can use hangar capacity expressed in the same size units as aircraft: external volume with {0} m added to each dimension × {1} ÷ hangar volume per craft. Only ships that fit entirely within one stowage or multipurpose compartment are selectable. Saved designs are supported.",
  "艦を搭載": "Embark Ship",
  "{2}{3} · {4} m · サイズ {5}": "{2}{3} · {4} m · Size {5}",
  "格納区画に入る艦がありません。格納区画を大きくすると、小型艦を積めるようになります。": "No ships fit the current hangar compartments. Enlarge a hangar to embark small ships.",
  "航空区画（格納・兼用）を配置すると、小型艦を積めます。": "Place an aviation compartment for stowage or multipurpose use to embark small ships.",
  "入らない艦：{0}{1}": "Ships That Do Not Fit: {0}{1}",
  "{0} · 内寸 {1} · {2} · {3}": "{0} · Internal Dimensions {1} · {2} · {3}",
  "容量 {0}・空き {1} サイズ": "Capacity {0} · Free {1} Size Units",
  "格納容量なし": "No Stowage Capacity",
  "出入口 {0}": "Entrance {0}",
  "ハッチにつながっていません": "Not Connected to a Hatch",
  "内寸は区画の外形（全長 × 全幅 × 高さ）、出入口はハッチの開口（長辺 × 短辺）です。機体は小さい方の2辺が開口を通れば発艦できます。区画を選んで、位置・寸法・用途・接触面の開口を編集できます。": "Internal dimensions are compartment length × width × height; entrances use hatch opening dimensions (long side × short side). A craft can launch if its two smaller dimensions fit through the opening. Select a compartment to edit its position, dimensions, function and openings on contact surfaces.",
  "「区画」から航空区画を配置してください。": "Place an aviation compartment from Compartments.",
  "スライド扉の開閉を確認": "Preview Sliding Doors",
  "上甲板・腹部の扉は左右へ、舷側の扉は上下へ移動します。観閲式と戦闘開始時は閉じ、発艦指示で4秒かけて開き、発艦完了・中止後に閉じます。": "Dorsal and ventral doors slide sideways; side doors slide vertically. They close for fleet reviews and at battle start, open over four seconds on launch orders, and close after launch completion or cancellation.",
  "{8}の使用量": "{8} Usage",
  "容量超過": "Over Capacity",
  "寸法指定": "Specified Dimensions",
  "容量不足で {0} {1}が未搭載。": "Insufficient capacity: {0} {1} not embarked.",
  "外形 {0}{1} · 1両 {2} サイズ · 搭載 {3} / {4} 両{5}{6}{7}{8}": "Dimensions {0}{1} · Size per Vehicle {2} · Embarked {3} / {4} Vehicles{5}{6}{7}{8}",
  "（輸送機に積載 {0}・格納庫 {1}）": "({0} in Transports · {1} in Hangars)",
  "· 1両に兵員 {0} 名": "· {0} Troops per Vehicle",
  "{0} {1} 両が未搭載。": "{0}: {1} vehicles not embarked.",
  "寸法の合う格納区画も輸送機もなく": "No suitably sized hangar compartment or transport",
  "格納庫の空きか配置が足りず": "Insufficient hangar space or unsuitable layout",
  "この車両は艦が着陸して降ろします。": "The ship must land to unload this vehicle.",
  "この車両を積める輸送機がありません（降ろせません）。": "No transport can carry this vehicle; it cannot be landed.",
