  "部隊 {17} の{18}": "Ground Unit {17}: {18}",
  "空きまで搭載": "Fill Available Space",
  "車種": "Vehicle Type",
  "部隊 {1} の車種": "Ground Unit {1} Vehicle Type",
  "車両（輸送機の積載区画・格納庫の空き）": "Vehicles (Transport Cargo Space / Free Hangar Space)",
  "降下（輸送機の1回の出撃）": "Landing Capacity (One Transport Sortie)",
  "車両は、まず内寸の合う輸送機の積載区画に、入らない分は格納庫に載ります。格納庫の車両と、1回で降ろしきれない兵員は2回目以降の便で降ろします。": "Vehicles are loaded first into dimensionally suitable transport cargo bays; the remainder use hangars. Vehicles in hangars and troops exceeding the first wave's capacity land in subsequent sorties.",
  "車両の積載": "Vehicle Load",
  "（うち車両に乗る {0} 名）": "(including {0} troops riding in vehicles)",
  "積める車両の大きさ": "Maximum Vehicle Dimensions",
  "{0} まで": "Up to {0}",
  "輸送機はありませんが、この艦は着陸して地上部隊を降ろせます。": "No transports are available, but this ship can land to disembark ground forces.",
  "輸送機（シャトル・揚陸艇・降下バージ）がありません。地上部隊は輸送機に載せて降ろします。「航空」タブで輸送機を搭載してください。": "No transports (shuttles, landing craft or drop barges) are available. Ground forces need transports to land. Embark them in the Aviation tab.",
  "この艦はリパルサーリフト（支持 {0}）が艦の質量（{1}）を支えるので、着陸して地上部隊と車両をそのまま降ろせます。": "Repulsorlift support ({0}) exceeds ship mass ({1}), so this ship can land and unload troops and vehicles directly.",
  "できる（車両を直接降ろせる）": "Available (Vehicles Can Disembark Directly)",
