  "部品数の上限（区画 {0}・装備 {1}）を超えるため貼り付けられません": "Cannot paste: component limits exceeded ({0} compartments; {1} equipment items)",
  "{0} 個を貼り付け": "Paste {0} Items",
  "貼り付けました：区画・構造物 {0}・装備 {1}": "Pasted {0} compartments/structures and {1} equipment items",
  "まとめて移動": "Move Selected",
  "区画・構造物・装備をタップして選択に加え、もう一度タップで外します。左右・上下対称がオンなら対の部品も一緒に選びます。内部の区画は「透視」で選べます。": "Tap compartments, structures or equipment to add them to the selection; tap again to remove them. Enabled symmetry also selects mirrored counterparts. Use X-ray to select internal compartments.",
  "区画・構造物をすべて": "All Compartments / Structures",
  "構造物だけ": "Structures Only",
  "装備をすべて": "All Equipment",
  "移動量（m）": "Displacement (m)",
  "対称の相手も選んでいれば鏡写しに動きます。装備は移動後に近くの面へ据え直します。": "Selected symmetry counterparts move in mirrored directions. Equipment is reseated on nearby surfaces after moving.",
  "艦首へ": "Toward Bow",
  "艦尾へ": "Toward Stern",
  "左舷へ": "To Port",
  "右舷へ": "To Starboard",
  "{5} 個を貼り付け": "Paste {5} Items",
  "貼り付けた部品はそのまま選択されるので、続けて「まとめて移動」で位置を整えられます。別の艦へは、設計図から艦を開いてこの画面で貼り付けます。クリップボードはこの端末のブラウザに残ります。": "Pasted components stay selected, so use Move Selected to position them. To paste into another ship, open its design and return here. The clipboard is kept in this device's browser.",
