  "全長 1,600 m・全幅 1,000 m のくさび形船体（艦種：デストロイヤー）を用意しました。インペリアル級の要点は": "A wedge hull 1,600 m long and 1,000 m wide is ready (Destroyer). Three key features of an Imperial-class are:",
