  "をタップします。「左右対称」がオンなので、中心から離れた所をタップすると左右一対になります。中央にもう1基置けばインペリアル級らしい3基です。炉とノズルの間の機関は自動でつながります。": ". Left/right symmetry places a pair when tapped off-center. Add a third on the centerline for the Imperial-class arrangement. Engine bodies connect reactors and nozzles automatically.",
