  "艦橋本体の上": "Tap the top of the bridge body",
  "を中心から少しずらしてタップすると、左右一対の球形ドームが据わります。インペリアル級の艦橋の上にある、あの2つの球です。": " slightly off-center to place a pair of spherical domes: the two spheres above an Imperial-class bridge.",
