  "環状母艦": "Ring Carrier",
  "八連装主砲8基・補助重砲13基・左右トレンチ砲。航空隊は格納区画の実容積に従い、主機は旧作例の物理寸法を保持します。船体・段状甲板は通常部品、艦橋は既存ISD本体です。": "Eight octuple main turrets, thirteen auxiliary heavy turrets and trench guns on both sides. Air wing capacity follows actual hangar volume; engines retain the previous example's physical dimensions. Hull and stepped decks use standard components; the bridge uses the existing ISD body.",
  "船体断面・舷側トレンチ・都市段丘・腹部構造と13基の機関を原型モデルから実測して構成。艦橋本体と標的追跡ドームは原型の形状です。左右の上下甲板・中央・トレンチを武装化。搭載機は50個飛行隊・3,600機、主機クラス2.0、出力はインペリアル級200隻分。持ち場の 95% 近くを艦内運用の自動化装置が受け持ち、必要乗員は公式の約28万人（v19.1）。自動化装置が止まると操艦不能になる危険を抱えています。": "Hull sections, side trenches, urban terraces, ventral structures and thirteen engines are measured from the original model. The bridge body and tracking domes retain the original shapes. Upper/lower decks, centerline and trenches on both sides carry weapons. Complement: 50 air wings / 3,600 craft; hyperdrive class 2.0; output equivalent to 200 Imperial-class ships. Automation covers nearly 95% of stations, bringing required crew near the published 280,000 (v19.1). Automation failure risks loss of ship control.",
  "指定表 Ships!S34": "Reference Spreadsheet, Ships!S34",
  "8門×40 TT。独立した砲塔・旋回台・装甲囲い。上面・下面・トレンチ壁へ取り付けられます。": "8 barrels × 40 TT. Separate turret, traversing platform and armored enclosure. Mounts on upper/lower surfaces and trench walls.",
  "舷側ケースメイト砲": "Broadside Casemate Gun",
  "8門×40 TT。側壁に砲口を外向きに装着。左右±65°・上下±20°の範囲から船体の遮蔽を差し引きます。充電装置は壁の内側です。": "8 barrels × 40 TT. Mounts on a side wall with muzzles outward. Arc: ±65° horizontally and ±20° vertically, excluding hull-obstructed directions. The charger sits inside the wall.",
  "口径・連射速度はゲーム用設定": "Caliber and Firing Rate Are Gameplay Settings",
  "ケースメイト中砲": "Medium Casemate Gun",
  "トレンチや舷側の壁に埋め込む連装砲（2門×16 TT）。砲郭と充電装置は船体の内側にあり、外には装甲砲門と砲身だけが出る。射程は約9 kmと短いが、同じ電力で長射程砲の約1.8倍の砲火を出せる。左右±65°・上下±20°、船体で遮蔽される方向は射撃不可。": "Twin guns recessed into trench or side walls (2 barrels × 16 TT). Casemate and charger are inside the hull; only the armored gunport and barrels project outside. Short range of approximately 9 km, but about 1.8 times the firepower of long-range guns for the same power. Arcs: ±65° horizontally, ±20° vertically; hull-obstructed directions cannot be fired upon.",
  "ケースメイト軽砲": "Light Casemate Gun",
  "壁に埋め込む連装の軽砲（2門×400 GT）。小型艦艇と戦闘機向け。左右±65°・上下±20°、船体で遮蔽される方向は射撃不可。": "Twin light guns recessed into a wall (2 barrels × 400 GT), intended for small ships and fighters. Arcs: ±65° horizontally and ±20° vertically; hull-obstructed directions cannot be fired upon.",
  "作例の砲座がありません:": "Example gun mount not found:",
  "トレンチの内壁がありません:": "Trench inner wall not found:",
