  "不明（出典未記載）": "Unknown (No Source Given)",
  "アクラメイター級の形状は、ユーザーが提供した STL ファイル（Acclamator.stl、作者・ライセンス表記なし）から実測した。": "Acclamator-class geometry was measured from the user-provided Acclamator.stl file, which included no author or license attribution.",
  "752 m（正史）。ユーザー提供の STL ファイル（Acclamator.stl、Blender 2.82 書き出し、作者・ライセンス表記なし）の実測形状を正史の全長に等倍で合わせた（モデルは幅 425 m・高さ 134 m で、正史の 460 m・飛行時 183 m より平たい。形状はモデルに従った）。尾部ブロック、V 字底の中央胴（ブリムの帯は胴自身の幅で取る）、腹部ブロック上の前部胴を1本の主船体として断面ごとに合わせ、周囲の翼状ブリムとその上縁の張り出し、腹部前方ブロック、尾部下部ブロック、背部テラス・ブロック、KDY 標準の艦橋塔モジュール、司令塔走査・通信機器ハウジング、艦尾機関間の張り出しを構造物として組み直した。速さを優先した設計（正史の最大加速 3,500 G に近づける）：主推進機関2基の推進粒子流路を艦尾面から腹部ブロックの付け根まで（x 92〜297 m）、補助推進機関2基を中央胴の先まで（x 118〜250 m）艦内へ延ばし、推進機関の容積は 31.1 万 m³。DK 断面図のとおり艦体は空洞を多く含む構造を慣性補償フィールドで保つものとして、ブリムと上縁の張り出し、腹部前方ブロック、尾部下部ブロック、背部テラス、艦橋塔、ハウジングを軽構造とし、外殻装甲は 0.16 m（重装甲より速さ）。機関は DK 断面図に従う。主反応炉は艦橋塔の下の船体テラスに内蔵（腹部ドームなし）、艦首に副反応炉、補助推進機関には専用の小型炉。尾部の先端にハイパードライブ発生装置（クラス 0.6）、尾部に慣性補償フィールドの脊柱導管、中央胴上部に構造維持フィールド導管、区域シールド発生器ノード4基、反応物凝縮サイロ4基と反応物バルブ・モジュール、前部ブリムに貨物庫約 17.6 万 m³（標準寸法の点防御砲の乗員 96 名ぶん居住容積を空けるため、高さを 13 m から 11.2 m に詰めた）、艦橋塔に無窓式の主艦橋と戦闘指揮室、ハウジングに走査・通信機器、集合ホール、ガンシップ周回整備レールと重戦闘車両整備ベイ。反重力リパルサーリフトが艦の全質量を支え、自ら着陸して地上部隊と車両を降ろせる。格納区画は腹部ブロックの揚陸甲板（前に AT-TE、上にガンシップ搭乗甲板。竜骨の降下ハッチ）、前部ガンシップ甲板、ブリムの前後のガンシップ甲板（下面ハッチ）と背部の兵站受入ベイ（上面ハッチ）。兵装は四連ターボレーザー砲塔 12 基（4門×200 GT）、点防御レーザー砲 24 基、ミサイル・魚雷発射管 4 基。乗艦はクローン・トルーパーと支援要員 1万6,000 名（正史どおり）、LAAT/i 32 機、LAAT/c 9 機、AT-TE 48 両（9 両は LAAT/c に積載）、BARC スピーダー 320 両（128 両は LAAT/i に積載）。延ばした推進機関に中央胴の格納庫と揚陸甲板の後部を譲ったため、SPHA-T（全長 140 m）が入る格納区画はなくなり、ガンシップは正史の 80 機から 41 機に減らした（兵員を優先）。必要乗員は艦の規模・格納庫・兵装から計算した値（正史は 700 名）。最大加速度は約 3,030 G：正史の 3,500 G には、推進機関を実測の噴射口の大きさのまま延ばせる限り延ばしても、装甲を約 0.09 m まで削らないと届かないため、そこまでは削っていない。出力 2×10²³ W、シールド蓄積 2×10²⁴ J（シールド出力は全出力の 35%＝7×10²² W）。": "752 m (canon). The measured shape of the user-provided STL file (Acclamator.stl, exported from Blender 2.82, with no author or license attribution) was uniformly scaled to canonical length. The resulting model is 425 m wide and 134 m high, flatter than the published 460 m beam and 183 m flight height; geometry follows the model. Tail block, V-bottom central hull (including brim width) and forward hull above the ventral block form one section-defined hull. Surrounding wing-like brims and lips, forward ventral block, lower tail block, dorsal terraces, standard KDY bridge tower module, conning tower scanning/communications housing and projection between aft engines are rebuilt as structures. The design favors speed, targeting the canonical 3,500 G: two main engine particle-flow channels extend from the stern to the ventral block root (x 92–297 m), and two auxiliaries extend into the central hull (x 118–250 m), giving 311,000 m³ of engine volume. Following DK cross-sections, a largely hollow structure is supported by inertial compensation fields. Brims, lips, ventral and tail blocks, dorsal terraces, bridge tower and housing use light structure; outer armor is 0.16 m, favoring speed over heavy protection. Machinery follows the DK layout: main reactor within the terrace beneath the bridge tower, with no ventral dome; secondary reactor forward; dedicated small reactors for auxiliary engines; class 0.6 hyperdrive at the tail tip; inertial compensation spinal conduit in the tail; structural integrity conduit above the central hull; four local shield nodes; four reactant condensation silos and valve modules; approximately 176,000 m³ of forward-brim cargo space (height reduced from 13 to 11.2 m to accommodate 96 standard point-defense gun crew); enclosed main bridge and combat command room in the tower; scanning/communications equipment in the housing; assembly hall; gunship maintenance circuit and heavy vehicle bay. Repulsorlifts support the ship's entire mass for direct troop and vehicle landing. Hangars comprise the ventral landing deck (AT-TEs forward, gunship embarkation deck above, keel landing hatch), forward gunship deck, fore/aft brim gunship decks with ventral hatches, and dorsal logistics receiving bay with an upper hatch. Armament: twelve quad turbolaser turrets (4 × 200 GT), 24 point-defense laser mounts and four missile/torpedo tubes. Complement: 16,000 clone troopers and support personnel as in canon, 32 LAAT/i, nine LAAT/c, 48 AT-TE (nine aboard LAAT/c), and 320 BARC speeders (128 aboard LAAT/i). Extended engines displace the central hangar and aft landing deck, leaving no compartment large enough for the 140 m SPHA-T and reducing gunships from the canonical 80 to 41 to prioritize troops. Required crew is calculated from ship size, hangars and weapons; canon specifies 700. Maximum acceleration is approximately 3,030 G. Reaching 3,500 G with engine channels extended as far as their measured exhaust dimensions allow would require armor around 0.09 m, so the design retains thicker armor. Output: 2×10²³ W. Shield capacity: 2×10²⁴ J; shield output is 35% of total, or 7×10²² W.",
