  "ユーザー提供の STL ファイル（ArquitensClassCruiser.STL、3ds Max STLEXP 書き出し）": "User-provided STL file (ArquitensClassCruiser.STL, exported with 3ds Max STLEXP)",
  "アークワイテンス級軽クルーザーの形状は、ユーザーが提供した STL ファイル（ArquitensClassCruiser.STL、作者・ライセンス表記なし）から実測した。": "Arquitens-class light cruiser geometry was measured from the user-provided ArquitensClassCruiser.STL file, which included no author or license attribution.",
  "325 m（正史。クローン戦争期に共和国宇宙軍が使った軽クルーザーの値。帝国時代に同じ船体形状で作り直され帝国宇宙軍で使われた司令クルーザー型は、資料により 230 m）。ユーザー提供の STL ファイル（ArquitensClassCruiser.STL、3ds Max 書き出し、作者・ライセンス表記なし）の実測形状を全長 325 m に等倍で合わせた。中央推進ポッド内の芯、細い首部、全幅のベルトを持つ菱形の胴、艦首の2本の突起を1本の主船体として断面ごとに合わせ、突起の間の切れ込みは立体の削り取りで抜いた。艦橋塔と艦橋の窓帯、推進ポッド間の機関架台と支柱、後部翼板、腹部キール、ベルト端の円形ポッド、ベルトの斜め肋材、艦首分岐部の中央ブロック、舷側と突起の砲座、3つの推進ポッドの外殻を構造物として組み直した。推進ポッドはそれぞれイオン・ドライブ1基とポッド先端の専用反応炉を持ち、胴の中央の主反応炉が砲・シールド・艦内に給電する。背骨に沿ってハイパードライブ（クラス 2。正史の主機に合わせ、予備機は表現しない）、慣性補償装置、構造維持装置、ベルト内に偏向シールド発生器2基と反応物サイロ2基、艦橋塔に艦橋、その下の胴に戦闘情報センター。武装は正史の構成どおり、ターボレーザー砲台4基（ベルト端と突起の連装砲塔の位置に標準寸法の中ターボレーザー砲塔。ベルト端の砲座の側面は模型の 10 m 砲塔の大きさで 18 m の砲塔を載せられないため、その2基は砲座の上面に置いた）、四連レーザー砲台8基（艦橋塔の両脇の上面2・下面2の丸い砲塔の位置に標準寸法の点防御レーザー砲を前後に2基ずつ）、突起の前向きの震盪ミサイル発射管4基（外付け）、前部胴の下面のトラクター・ビーム投射機1基。兵装の再充電は最大連射の約 7%。乗員はゲームの規則で 325 名（正史の値は未確認。ファン資料の 750 名でも艦内の空き容積に収まる）、兵員100名（帝国宇宙軍兵とストームトルーパー）。帝国の司令クルーザー型は発着装置でセンチネル級着陸船1機または TIE/ln 2機などを扱えるが、模型に格納庫の開口がなく、ゲームの格納庫は開口のある船内区画として作る必要があるため、航空隊は載せていない。加速 約 1,630 G は3基のポッド機関からの値（正史の値は不明）。": "325 m (canonical Republic Navy light cruiser during the Clone Wars; some sources give 230 m for the Imperial command-cruiser version using the same hull form). The user-provided ArquitensClassCruiser.STL, exported from 3ds Max without author or license attribution, was uniformly scaled to 325 m. The central propulsion pod core, narrow neck, diamond-shaped body with full-width belt, and twin bow prongs form one section-defined hull; solid subtraction cuts the gap between prongs. Bridge tower and window band, inter-pod engine frame and struts, aft wing plates, ventral keel, circular belt-end pods, diagonal belt ribs, central bow-fork block, broadside/prong gun positions and three propulsion pod shells are rebuilt as structures. Each pod contains an ion drive and dedicated forward reactor; the central main reactor powers weapons, shields and ship systems. The spine carries a class 2 hyperdrive matching the canonical main drive (backup not represented), inertial compensators and structural integrity equipment. The belt contains two deflector shield generators and two reactant silos. The bridge sits in its tower with a combat information center below. Canonical armament layout is retained: four turbolaser batteries use standard medium turrets at twin-turret positions on the belt ends and prongs. Belt-end side mounts sized for 10 m model turrets cannot accept the 18 m standard turrets, so these two sit atop their platforms. Eight quad laser batteries use paired standard point-defense mounts at the round upper/lower positions beside the bridge tower. Four external forward-firing concussion missile tubes sit in the prongs; one tractor-beam projector sits beneath the forward hull. Recharge supports about 7% of maximum sustained weapon fire. Gameplay rules require 325 crew (canonical crew unconfirmed; the fan-source figure of 750 also fits available volume) plus 100 Imperial Navy troops/stormtroopers. The Imperial command cruiser can handle a Sentinel landing craft or two TIE/ln via launch facilities, but the model has no hangar opening and the game requires an internal bay with an opening, so no air wing is included. Acceleration of approximately 1,630 G follows the three pod engines; no canonical figure is known.",
  "150 m・11基の機関・ターボレーザー砲塔4基（正史の連装2基は柱の上下の中ターボレーザー砲塔、単装4基は標準寸法の軽ターボレーザー砲塔が砲塔台座に1基ずつしか載らないため2基）・点防御4基。背骨の円筒1本を船体とし、外形は原型モデルから実測した構造物": "150 m; eleven engines; four turbolaser turrets. The two canonical twin mounts use medium turrets above/below the pillar; the four single mounts are represented by two standard light turrets because only one fits each platform. Four point-defense mounts. A single cylindrical spine forms the hull; measured structures reproduce the original model's exterior.",
