  "構造維持装置がありません（小型の機体は船体の強度だけで飛べます）。": "No structural integrity system is fitted. Small craft can fly using hull strength alone.",
  "シールド発生器がありません": "No shield generator is fitted.",
  "シールド発生器がありません（TIE のように機動と数で補う機体もあります）。": "No shield generator is fitted. Some craft, such as TIEs, compensate with maneuverability and numbers.",
  "艦橋がありません": "No bridge is fitted.",
  "操縦席（またはドロイド制御中枢）がありません。命中率が大きく落ちます。": "No cockpit or droid control core is fitted. Accuracy is greatly reduced.",
  "操縦席（またはドロイド制御中枢）がありません。": "No cockpit or droid control core is fitted.",
  "誘導式の対艦魚雷。半分はシールドを抜ける。": "Guided antiship torpedo. Half its damage penetrates shields.",
  "プロトン魚雷と同じ弾体のイオン弾頭。シールドに3倍で効き、抜けた分は蓄電を奪い反応炉を麻痺させる（船体への損害は小さい）。": "An ion warhead in a proton-torpedo body. It deals triple damage to shields; penetration drains stored power and disrupts reactors, with little hull damage.",
  "エネルギー魚雷": "Energy Torpedo",
  "ドロイド戦闘機の軽い魚雷（ヴァルチャー級）。": "Light torpedo used by Vulture droid fighters.",
  "細く速い誘導ミサイル。弾頭は魚雷より小さい。": "A slender, fast guided missile with a smaller warhead than a torpedo.",
  "プロトン爆弾": "Proton Bomb",
  "誘導のない爆弾。目標の真上で落とすので、攻撃航過の最も近い所で放つ。": "An unguided bomb released directly over the target, at the closest point of the attack pass.",
  "弾の寸法・質量は正史・レジェンズに数値がないため、作例の発射管（実測）に収まる大きさとしたゲーム用仮定。威力はゲーム用仮定（正史の搭載で1回目の攻撃航過が航行の機種表の対艦値に近くなる値）。": "Canon and Legends provide no ammunition dimensions or mass, so game values fit the measured example launchers. Damage is also a game assumption, tuned so the first pass with canonical loads approximates each craft's antiship rating.",
  "発射管の弾倉": "Launcher Magazine",
  "弾倉": "Magazine",
  "翼下パイロン": "Underwing Pylon",
  "震盪ミサイル発射管2基・計12発（Wikipedia「A-wing」諸元。Wookieepedia：Dymek HM-6 各6発）": "Two concussion-missile launchers, twelve rounds total (Wikipedia: A-wing specifications; Wookieepedia: Dymek HM-6, six rounds each).",
  "プロトン魚雷発射管2基（Wikipedia「List of Star Wars starfighters」の諸元）。弾数は記載がなく、各3発（X ウイングの MG7 と同じ）": "Two proton-torpedo launchers (Wikipedia: List of Star Wars starfighters). Ammunition unspecified; three each, matching the X-wing's MG7.",
  "プロトン魚雷6発（Dougherty ほか 2020, pp. 82–83。Wikipedia「List of Star Wars starfighters」）": "Six proton torpedoes (Dougherty et al., 2020, pp. 82–83; Wikipedia: List of Star Wars starfighters).",
  "震盪ミサイル発射管（Before the Awakening。Wookieepedia「Z-95 Headhunter」）。弾数は記載がなく、各6発（A ウイングの HM-6 と同じ）": "Concussion-missile launchers (Before the Awakening; Wookieepedia: Z-95 Headhunter). Ammunition unspecified; six each, matching the A-wing's HM-6.",
  "震盪ミサイル発射管2基（Star Wars: On the Front Lines, 2017・StarWars.com Databank）。弾数は記載がなく、各6発": "Two concussion-missile launchers (Star Wars: On the Front Lines, 2017; StarWars.com Databank). Ammunition unspecified; six each.",
  "プロトン魚雷・震盪ミサイル・爆弾（精密爆撃用の下向き光学センサー。StarWars.com Databank）。数は記載がなく、標準の弾倉（魚雷各3・ミサイル各6・爆弾8）": "Proton torpedoes, concussion missiles, and bombs, with a downward optical sensor for precision bombing (StarWars.com Databank). Counts unspecified; standard magazines hold three torpedoes or six missiles per launcher, plus eight bombs.",
  "胴体にエネルギー魚雷発射管2基（StarWars.com Databank「Vulture Droid」）。弾数は記載がなく各2発。バズ・ドロイド・ミサイルは震盪ミサイル2発で代用": "Two fuselage energy-torpedo launchers (StarWars.com Databank: Vulture Droid). Ammunition unspecified; two each. Two concussion missiles substitute for buzz-droid missiles.",
  "居住区": "Quarters",
  "最低限の乗員にも届かず、戦闘では動けません。": "Crew is below the minimum; the ship cannot maneuver in combat.",
  "戦闘では射撃と応急が遅れます。": "Weapons fire and damage control are slower in combat.",
  "地上部隊の車両 {0} 両が格納庫に入りません{1}。車両は航空機と同じ格納庫に寸法で入るか、輸送機の積載区画に載ります。": "{0} ground vehicles do not fit in the hangar{1}. Vehicles must fit inside aircraft hangars or transport cargo compartments.",
