  "（格納庫の容量か配置の不足）": " (Insufficient Hangar Capacity or Space)",
  "地上部隊（{0}）を降ろす輸送機（シャトル・揚陸艇）がありません。地上部隊は輸送機に載せて降ろします。": "No shuttle or landing craft can deploy the ground force ({0}). Ground forces require transports to land.",
  "ドロイド {0} 体": "{0} Droids",
  "{0}{1} を積める輸送機（揚陸艇・降下バージなど）がありません。車両は輸送機の積載区画に入る大きさのものだけを降ろせます。": "No landing craft, drop barge, or other transport can carry {0}{1}. Only vehicles that fit a transport's cargo compartment can land.",
  "人の乗員だけでは 35% に届かないため、装置が止まれば即座に操艦不能です。": "Human crew cover less than 35% of stations; failure of automation immediately disables ship control.",
  "装置の {0} 名分は余っています（受け持てるのは全持ち場の {1}% まで）。": "Automation capacity for {0} crew is unused; it can cover at most {1}% of all stations.",
  "地上部隊（{0}）が、乗員を除いた空き容積の兵員枠（兵員 {1} 名分）を超えています。": "The ground force ({0}) exceeds the remaining troop capacity of {1} after crew accommodation.",
  "停止保管ドロイド {0} 体": "{0} Dormant Droids",
