  "母港は{0}。修理中・改装中・就役準備中・回航中の艦は出撃できません（残り時間を表示）。新しく加えた艦は就役準備のあとに、別の星系にいる任務群へ移した艦は回航を終えてから出撃できます。任務群は{1}〜{2}隻、パトロールには任務群ひとつで出ます。艦名は自由に変えられます。編成は任務の保存データに記録されます。": "Home port: {0}. Ships under repair, refitting, commissioning or on passage cannot sail (time left is shown). A newly added ship sails after commissioning; a ship moved to a task force in another system sails once its passage is done. Task forces have {1}–{2} ships, and a patrol takes one task force. Ship names can be changed freely. The order of battle is kept in the mission save.",
  "{0}。敵は{1}、母港は{2}。「編成完了」で銀河図に出ます。任務群は{3}〜{4}隻、パトロールには任務群ひとつで出ます。艦名は自由に変えられます。編成は任務の保存データに記録されます。": "{0}. The enemy is the {1}; home port {2}. Press “Done” to go out to the galaxy map. Task forces have {3}–{4} ships, and a patrol takes one task force. Ship names can be changed freely. The order of battle is kept in the mission save.",
