  "6時間待機": "Wait 6 hours",
  "次の艦が復帰するまで（{0}）": "Until the next ship is back ({0})",
  "時間はパトロールの航行・ジャンプ、艦隊戦の進出と戦闘、待機で進みます。そのあいだに修理が進み、敵艦隊が現れたり撤収したりします。": "Time passes on patrol (sailing and jumps), in fleet battles (the passage there and the fighting) and while waiting. Meanwhile repairs go on, and enemy fleets appear and withdraw.",
  "任務群をひとつ選んで、いる星系から銀河を巡回します。": "Choose one task force; it patrols the galaxy from the system it is in.",
  "{0} · {1}から": "{0} · from {1}",
  "{0}から": "from {0}",
  "旗艦 {0}": "Flagship {0}",
  "ハイパードライブ クラス {0}（任務群でいちばん遅い艦）。": "Hyperdrive class {0} (the slowest ship in the task force).",
  "{0}からパトロールに出る": "Patrol from {0}",
  "旗艦（任務群の先頭の出撃可能艦）を操艦し、僚艦は隊形を組んで続きます。星図でほかの星系へジャンプでき、ハイパースペースの航行時間は実際の時間です（「スキップ」で到着の数秒前まで進められます）。民間船が行き交い、ときおり敵艦が現れます。敵艦隊のいる星系では敵の哨戒艦がすぐに来ます。「帰還」でパトロールを終え、損傷した艦はドックに入ります。": "You steer the flagship (the first ready ship of the task force); the escorts follow in formation. Jump to other systems from the star map; hyperspace passages take their real time (“Skip” brings you to a few seconds before arrival). Civilian ships come and go and enemy ships turn up now and then; in a system with an enemy fleet its pickets come at once. “Return” ends the patrol, and damaged ships go into dock.",
  "出撃できる艦のいる任務群がありません。修理が終わるのを待つか、艦隊編成で艦を加えてください。": "No task force has ships ready to sail. Wait for repairs or add ships in the Order of Battle.",
