  "パトロール終了": "Patrol Ended",
  "敵艦隊を選んで任務群を送り、その星系の宙域で戦います。": "Choose an enemy fleet and send task forces; the battle is fought in the area around its system.",
  "この星系にいます": "In this system",
  "到着まで {0}": "{0} to arrive",
  "自軍 1 : 敵 {0}": "Us 1 : enemy {0}",
  "{0}（自軍 {1} 隻・敵 約 {2} 隻）": "{0} (us {1} ships, enemy about {2})",
  "一度に出せるのは {0} 隻までです。任務群を減らしてください。": "At most {0} ships can sail at once. Pick fewer task forces.",
  "{0}へ出撃": "Sail to {0}",
  "{0}へ出撃（到着まで {1}）": "Sail to {0} ({1} to arrive)",
  "敵艦隊は銀河のあちこちの星系に現れ（強さはさまざま）、2〜3日で撤収します。戦場はその星系を中心とする一辺500光年の宙域で、敵は自分の勢力圏の側から、自軍は来た方角から入ります。戦闘のあと、損傷した艦は損傷に応じた時間ドックに入ります（損傷度 × 8時間 × 艦の大きさ。航行不能だった艦はさらに長く）。撃沈・拿捕された艦は編成から消え、敵のいる星系に残された航行不能艦は放棄されます。拿捕した敵艦は改装のあと艦隊に加わります。": "Enemy fleets appear in systems across the galaxy (of varying strength) and withdraw after 2–3 days. The battle area is 500 light-years square around the system; the enemy comes in from its own side of the galaxy and we come in from the way we sailed. After a battle, damaged ships go into dock for a time that depends on the damage (damage × 8 hours × ship size; longer for ships that were disabled). Sunk and captured ships leave the order of battle, and disabled ships left in a system where the enemy remains are abandoned. Captured enemy ships join the fleet after a refit.",
  "任務：{0}で{1}と交戦。{2}の航行ののち、敵は勢力圏の側（{3}）から宙域に入っているとみられます。位置は不明です。": "Mission: engaging {1} at {0}. After a passage of {2}, the enemy is thought to have entered the area from its own side ({3}). Its position is unknown.",
  "任務：{0}で{1}と交戦。敵は勢力圏の側（{2}）から宙域に入っているとみられます。位置は不明です。": "Mission: engaging {1} at {0}. The enemy is thought to have entered the area from its own side ({2}). Its position is unknown.",
  "任務：{0}で{1}と交戦。{2}の航行ののち、敵は勢力圏の側から宙域に入っているとみられます。位置は不明です。": "Mission: engaging {1} at {0}. After a passage of {2}, the enemy is thought to have entered the area from its own side. Its position is unknown.",
  "任務：{0}で{1}と交戦。敵は勢力圏の側から宙域に入っているとみられます。位置は不明です。": "Mission: engaging {1} at {0}. The enemy is thought to have entered the area from its own side. Its position is unknown.",
  "銀河図へ戻る（戦果を確定）": "Back to the galaxy map (settle the outcome)",
  "銀河図へ戻りますか？": "Return to the galaxy map?",
  "撤退しますか？": "Withdraw?",
  "戦果を確定して銀河図に戻ります。": "The outcome is settled and you return to the galaxy map.",
  "戦場を離れて銀河図に戻ります。航行不能の艦は、敵のいる星系に残っていれば放棄されます。ほかの艦は損傷に応じてドックに入ります。": "You leave the battle and return to the galaxy map. Disabled ships are abandoned if the enemy remains in the system; the others go into dock according to their damage.",
  "銀河図へ戻る": "Back to the galaxy map",
  "撤退して銀河図へ": "Withdraw to the galaxy map",
