  "0 に戻す": "Reset to 0",
  "移動を確定": "Apply Move",
  "緑の枠が移動先です（赤は配置できない位置）。相対位置を保ったまま動き、3D表示で選択部品をドラッグしても動かせます。": "Green outlines show where the parts go (red: not allowed there). They keep their relative positions; you can also drag the selected parts in the 3D view.",
  "回転角（度）": "Rotation angle (degrees)",
  "まとめて（全体の中心）": "Together (about the selection's center)",
  "個別（それぞれの中心）": "Individually (each about its own center)",
  "回転を確定": "Apply Rotation",
  "構造物・区画・円筒・ノズルの向きが変わります（球形の設備は位置だけ）。装備は回した先の面に据え直します。左右対称がオンなら対の部品は鏡写しに回ります。": "Structures, compartments, cylinders and nozzles turn (spherical equipment only changes position). Fittings are re-seated on the surface where they end up. With Left/Right Symmetry on, the paired parts turn as mirror images.",
  "整列・等間隔": "Align & Space Evenly",
  "整列を確定": "Apply Alignment",
  "等間隔は両端の部品を動かさず、部品の大きさを含めた隙間が等しくなるよう中間を並べ直します（3つ以上）。グループは1つの部品として扱います。": "Even spacing keeps the two end parts in place and rearranges the ones between so the gaps between parts (sizes included) are equal (three or more). A group counts as one part.",
  "選んだ部品を1つのグループにまとめ、移動・回転・複製・撤去をまとめて行います（Ctrl+G、解除は Ctrl+Shift+G）。グループの部品をもう一度タップすると中の部品だけを選べます。グループは入れ子にでき、設計図と一緒に保存されます。部品カタログへの登録とは別の機能です。": "Gather the selected parts into one group to move, rotate, duplicate and remove them together (Ctrl+G; Ctrl+Shift+G to ungroup). Tap a part of a selected group again to pick just that part. Groups can nest and are saved with the design. This is separate from registering parts in the catalogue.",
  "一覧か3D表示で部品を選びます。Shift＋クリックで追加・解除、グループはまとめて選ばれます。": "Select parts in the list or the 3D view. Shift+click adds or removes; a group is selected as a whole.",
  "一覧か3D表示で部品を選びます。「複数」をオンにするとタップで追加・解除、グループはまとめて選ばれます。": "Select parts in the list or the 3D view. Turn on Multi to add or remove with each tap; a group is selected as a whole.",
  "{0} 個を選択": "{0} selected",
  "区画・構造物 {0}・装備 {1}": "{0} compartments/structures · {1} fittings",
  "グループ {0}": "{0} group(s)",
  "エラー {0}": "Errors {0}",
  "警告 {0}": "Warnings {0}",
  "情報 {0}": "Notes {0}",
  "正常 {0}/{1}": "OK {0}/{1}",
  "問題の報告がない部品": "Parts with no reported problem",
  "{0} 個を選択 →": "Select {0} →",
  "開く →": "Open →",
  "3D表示の左端に、「配置」では「配置・選択・撤去」、「編集」では「選択・複数・撤去」と「左右対称・上下対称」。区画・構造物・武装・艦橋のどの画面でも同じ場所で切り替えられる": "At the left edge of the 3D view: Place, Select and Remove under Place; Select, Multi and Remove under Edit; and Left/Right and Up/Down Symmetry. They sit in the same place on every compartment, structure, weapon and bridge screen",
  "配置と編集": "Place and Edit",
  "「配置」は置ける部品のカタログ、「編集」は置いた区画・装備の一覧と編集。一覧と3D表示の選択は同じもの": "Place is the catalogue of parts you can add; Edit lists the compartments and fittings already placed and edits them. The list and the 3D view share one selection",
  "「編集」で Shift＋クリック（スマホは道具バーの「複数」）で区画・構造物・装備を選択に加え・外し、まとめて移動・回転・整列・複製・撤去・コピー・切り取りができる。選択した部品は3D表示でドラッグしてもまとめて動く。コピーはこの端末に残るので、設計図から別の艦を開いて「貼り付け」できる（同じ座標／艦の寸法に合わせる）。Ctrl+C・Ctrl+X・Ctrl+V も使える": "Under Edit, Shift+click (Multi on the tool rail on phones) adds compartments, structures and equipment to the selection or removes them; then move, rotate, align, duplicate, remove, copy or cut them together. Dragging a selected part in the 3D view moves the whole selection. The clipboard persists on this device, so you can open another ship and paste at the original coordinates or scaled to the new hull. Ctrl+C, Ctrl+X and Ctrl+V also work",
  "選んだ部品を Ctrl+G（または「グループ化」）で1つのグループにすると、タップ1回でまとめて選べる。もう一度タップすると中の部品を選ぶ。Ctrl+Shift+G で解除。グループは設計図に保存され、部品カタログには登録されない": "Ctrl+G (or Group) makes the selected parts one group, selected with a single tap; tap again to pick a part inside it. Ctrl+Shift+G ungroups. Groups are saved with the design and are not added to the parts catalogue",
  "操作パネルの下に、エラー・警告・情報の件数と最初の問題を常に表示する。開いて項目を押すと該当部品を「編集」で選ぶ": "Below the editor panel, the counts of errors, warnings and notes and the first problem are always shown. Open it and press an item to select its parts under Edit",
  "スキンは塗装・装甲継ぎ目のみで、指揮能力は追加されません。指揮所は「配置 → 指揮・艦橋」から艦橋本体やポッドを配置します。": "Skins provide paint and armor seams only; they add no command capability. Place bridge bodies or pods under Place → Command & Bridge.",
  "「配置 → 指揮・艦橋 → 艦橋本体」で<b>インペリアル級 艦橋本体</b>を選んであります。甲板の<b>艦尾寄り（後ろから約1/5）の中心線</b>をタップしてください。前面の円筒ポッドが指揮所なので、置くだけで艦橋として働きます。": "The <b>Imperial-class Bridge Body</b> is selected under Place → Command & Bridge → Bridge Body. Tap the <b>deck centerline about one fifth of the hull length from the stern</b>. The front cylindrical pod provides command, so the bridge works as soon as it is placed.",
  "「配置 → 武装」で<b>6連装重ターボレーザー</b>を選んであります。<b>甲板の左右の縁</b>を艦尾から艦首へ2〜3か所タップしてください。左右対称なので1回で両舷に付きます。": "A <b>Sextuple Heavy Turbolaser</b> is selected under Place → Weapons. Tap two or three locations along the <b>deck edges</b>, working from stern to bow. Left/Right Symmetry installs guns on both sides with each tap.",
  "「配置 → 指揮・艦橋 → 艦橋本体」で": "Under Place → Command & Bridge → Bridge Body,",
  "「配置 → 武装」で": "Under Place → Weapons,",
