 "3D表示で頂点（十字）をタップして選び、ドラッグで動かします。「複数」がオンならタップで追加選択。座標はこの構造物自身の向きでの値です。面がつぶれる・交差する・裏返る移動は確定しません。元に戻す・やり直しに対応します。":"Tap a vertex (cross) in the 3D view to select it and drag to move it. With Multi on, taps add to the selection. Coordinates are in this structure’s own orientation. Moves that collapse, cross or turn faces inside out are not applied. Undo and redo work.",
