"機能付き主翼にすると、翼の内部に散逸装置・通常放熱装置・蓄電池・構造維持装置などを置けます。翼そのものには散逸能力はありません。": "A functional wing can hold dissipators, ordinary radiators, power cells, structural integrity units and the like inside it. The wing itself dissipates nothing.",
