"{0}（実線：展開・破線：収納・黄点：回転軸）": "{0} (solid: deployed, dashed: stowed, yellow dot: hinge)",
"形は展開状態で作ります。収納すると翼内の外装型散逸装置・放熱装置の面がふさがれて最大散逸能力が下がり、赤外・電磁の放射の一部が隠れます。負荷が収納時の能力以下なら実際の散逸量（と放射）は変わりません。武装は展開位置のまま表示します。": "Build the shape deployed. Stowed, the faces of the external dissipators and radiators in the wing are covered: their maximum capacity drops and part of their infrared and EM is hidden. While the load stays within the stowed capacity, the heat actually dissipated (and what is radiated) does not change. Weapons are drawn in the deployed position.",
"翼の形は「編集」タブの頂点編集で変えられます。中心が翼の内部にある設備が翼内の設備です。": "Change the wing's shape with vertex editing in the Edit tab. Equipment whose centre lies inside the wing counts as wing equipment.",
"多帯域は全帯域に広く、専用センサーはその帯域に強く働きます。ニュートリノは受動センサーだけが捉え、能動センサー（レーダー）は反射断面で探知します。": "A multi-band set covers every band; a dedicated sensor is strong in its own. Only passive sensors pick up neutrinos; the active sensor (radar) detects by reflecting cross-section.",
"放射は散逸装置の最大能力ではなく、その負荷で実際に散逸した熱から決まります（推進の排気と能動センサーの電波は別に加わります）。高エネルギー散逸とニュートリノ放射は架空技術のモデルです。": "Emission comes from the heat actually dissipated at that load, not from the dissipators' maximum capacity (drive exhaust and active-sensor transmissions add to it separately). High-energy dissipation and neutrino emission are a model of fictional technology.",
